"""Graveyard Golf headless test (Chrome + SwiftShader WebGL, served over a local web server)."""
import asyncio, os, re, glob, hashlib, base64
from playwright.async_api import async_playwright
import threading, http.server, functools, socketserver
from PIL import Image
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
class _Q(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
_srv = socketserver.ThreadingTCPServer(('127.0.0.1', 0), functools.partial(_Q, directory=ROOT)); _srv.daemon_threads = True
threading.Thread(target=_srv.serve_forever, daemon=True).start()
URL = 'http://127.0.0.1:%d/index.html' % _srv.server_address[1]
OUT = ROOT + '/test/shots/'; os.makedirs(OUT, exist_ok=True)
ARGS = ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--autoplay-policy=no-user-gesture-required']
R = []
def check(n, ok, info=''): R.append(bool(ok)); print(('PASS ' if ok else 'FAIL ') + n + (f' — {info}' if info != '' else ''), flush=True)

async def page(b, auto_q=False, manual=True, url=None, skip=False, locale='en-US', **kw):
    ctx = await b.new_context(accept_downloads=True, locale=locale, **kw)
    init = 'window.__ggSeed = 4242; window.__ggPDB = true;' + ('' if auto_q else 'window.__ggNoAutoQ = true;') + ('window.__ggManual = true;' if manual else '') + ('window.__ggSkipIntro = true;' if skip else '')
    await ctx.add_init_script(init + "try{if(!sessionStorage.getItem('ggInit')){sessionStorage.setItem('ggInit','1'); localStorage.clear();}}catch(e){}")
    pg = await ctx.new_page(); pg.set_default_timeout(300000); logs = []
    pg.on('console', lambda m: logs.append(f'{m.type}: {m.text}') if m.type == 'error' else None)
    pg.on('pageerror', lambda e: logs.append(f'PAGEERROR {e}'))
    await pg.goto(url or URL); await pg.wait_for_function('document.body.classList.contains("ready") && window.__gg', timeout=120000)
    return ctx, pg, logs

def pxs(im): return im.get_flattened_data() if hasattr(im, 'get_flattened_data') else list(im.getdata())
def mean(path): im = Image.open(path).convert('L'); px = pxs(im); return sum(px) / len(px)
def bright_share(path, thr=250):
    im = Image.open(path).convert('RGB').resize((320, 200)); px = pxs(im); return sum(1 for r, g, b in px if r >= thr and g >= thr and b >= thr) / (im.width * im.height)
def diff(a, b):
    A = Image.open(a).convert('L').resize((160, 100)); B = Image.open(b).convert('L').resize((160, 100)); pa, pb = pxs(A), pxs(B); return sum(abs(x - y) for x, y in zip(pa, pb)) / len(pa)
async def shot(pg, name, n=1):
    await pg.evaluate(f'__gg.step(1/30, {n})'); await pg.wait_for_timeout(500); await pg.screenshot(path=OUT + name); return OUT + name
async def mark(pg): return await pg.evaluate('__gg.log.length')
async def lg_since(pg, k): return await pg.evaluate(f'__gg.log.slice({k}).map(e => e.n)')
async def ready(pg): return await pg.evaluate('(() => { let i = 0; for (; i < 900 && !__gg.canShoot() && __gg.S.state === "play"; i++) __gg.stepq(1/30); return __gg.canShoot(); })()')
async def roll(pg, n=600): return await pg.evaluate(f'(() => {{ let i = 0; for (; i < {n} && __gg.S.phase === "roll"; i++) __gg.stepq(1/30); return __gg.S.phase; }})()')
async def pops_since(pg, k): return await pg.evaluate(f'(window.__pops || []).slice({k})')
async def npops(pg): return await pg.evaluate('(window.__pops || []).length')
BLACK = '''(n) => { const gl = __gg.renderer.getContext(), px = new Uint8Array(4); let k = 0; for (let i = 0; i < n; i++) { __gg.step(1/30); let lit = 0; for (const [fx, fy] of [[.5, .5], [.25, .3], [.75, .3], [.25, .75], [.75, .75]]) { gl.readPixels(Math.floor(gl.drawingBufferWidth * fx), Math.floor(gl.drawingBufferHeight * fy), 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px); if (px[0] + px[1] + px[2] >= 3) lit++; } if (!lit) k++; } return k; }'''
CLIP = '''(n) => { const bad = []; for (let i = 0; i < n; i++) { __gg.stepq(1/30); const c = __gg.camClip(); if (c) bad.push(c); } return bad.slice(0, 3); }'''
# wait until a shot (ang, pow) does what we want (obstacle timing), then take it
WAIT_SIM = '''([ang, pow, key, n]) => { for (let i = 0; i < n; i++) { const r = __gg.sim(ang, pow); if (key === 'pit' ? r.lost : r[key]) return __gg.shoot(ang, pow) ? i : -2; __gg.stepq(1/30); } return -1; }'''

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path='/usr/bin/google-chrome', headless=True, args=ARGS)
        # ================= opening: ball's-eye ride through The Mausoleum =================
