        f1 = await shot(pg, 'intro-f1.png', 8); check('intro: motion from the first frames (dolly in + putter backswing)', diff(f0, f1) > 1.0, round(diff(f0, f1), 2))
        lg = await pg.evaluate('__gg.log.map(e => e.n)'); check('intro: deep rumble + bass boom at the start', 'rumble' in lg and 'boom_bass' in lg, lg[:8])
        check('intro: the ghost putter is there', await pg.evaluate('__gg._dbg.putter.visible'))
        k = await mark(pg); await pg.evaluate('(() => { while (__gg.S.introT < 1.1) __gg.stepq(1/30); })()'); l = await lg_since(pg, k)
        check('intro: TOCK – the putt is the real game shot', 'putt' in l and await pg.evaluate('__gg.ball().state') == 'roll', sorted(set(l)))
        await pg.evaluate('__gg.stepq(1/30, 20)'); await shot(pg, 'intro-ride.png', 1)
        bk = await pg.evaluate(f'({BLACK})(12)'); check('intro: no black frames in the ride', bk == 0, bk)
        k0 = await mark(pg); tsmin = await pg.evaluate('(() => { let m = 9; for (let i = 0; i < 400 && __gg.S.wakeT == null && __gg.S.state === "intro"; i++) { __gg.stepq(1/30); m = Math.min(m, __gg.S.ts); } return m; })()')
        check('intro: slow motion as the ball nears the cup', tsmin < .5, tsmin)
        await pg.evaluate('__gg.stepq(1/30, 12)'); l = await lg_since(pg, k0)
        check('intro: the ball drops – THE GRAVEYARD WAKES (boom, deep bell, organ, crowd groan)', await pg.evaluate('__gg.S.wakeT != null') and all(x in l for x in ('boom_cine', 'bell_deep', 'hit_dram')) and sum(1 for x in l if x.startswith('org_')) >= 3, sorted(set(l))[:16])
        wk = await shot(pg, 'intro-wake.png', 1); check('wake frame: no glare', bright_share(wk) < .02, round(bright_share(wk), 4))
        await pg.evaluate('(() => { for (let i = 0; i < 200 && __gg.S.gt - __gg.S.wakeT < 1.1; i++) __gg.stepq(1/30); })()')
        wk3 = await pg.evaluate('[__gg.W.jacks.filter(j => j.on >= 1).length, __gg.W.jacks.length, __gg.W.handIM.count, __gg.W.ghosts.filter(g => g.g.visible).length]')
        check('intro: jack-o\'-lanterns ignite in a wave, zombie hands burst out, ghosts rise', wk3[0] > 10 and wk3[2] > 10 and wk3[3] > 3, wk3)
        check('intro: the HOLE IN ONE slab rises', await pg.evaluate('__gg._dbg.slab.visible && __gg._dbg.slab.position.y > -.6'), await pg.evaluate('__gg._dbg.slab.position.y'))
        cl = await pg.evaluate(f'({CLIP})(8)'); check('intro crane: camera never inside a wall or under the felt', not cl, cl)
        await pg.evaluate('(() => { for (let i = 0; i < 200 && __gg.S.titleT == null; i++) __gg.stepq(1/30); __gg.stepq(1/30, 3); })()')
        tt = await pg.evaluate("[+getComputedStyle(document.getElementById('oTitle')).opacity, new DOMMatrix(getComputedStyle(document.getElementById('oTitle')).transform).a]")
        check('intro: title slams in huge (scale punch, no shake)', tt[0] > .9 and tt[1] > 1.5, tt)
        sl = await shot(pg, 'intro-title.png', 6); check('intro title frame is bright and contrasty, no glare', mean(sl) > 30 and bright_share(sl) < .02, (round(mean(sl), 1), round(bright_share(sl), 4)))
        await pg.evaluate('__gg.stepq(1/30, 60)'); t2 = await pg.evaluate("new DOMMatrix(getComputedStyle(document.getElementById('oTitle')).transform)")
        check('intro: title recedes into the night (Star Wars style)', t2['a'] < 1, t2['a'])
        await pg.evaluate('(() => { for (let i = 0; i < 300 && __gg.S.state === "intro"; i++) __gg.stepq(1/30); __gg.step(1/30, 20); })()')
        check('intro ends in the menu by itself', await pg.evaluate('__gg.S.state') == 'menu' and await pg.is_visible('#menu.show'))
        check('menu: title, 9-hole round + duel', 'GRAVEYARD' in await pg.text_content('#menu h1') and '9 holes' in await pg.text_content('#btnCampaign') and 'Player 2' in await pg.text_content('#btnDuel'))
