        # mouse drag: pull back + release
        k = await mark(pg); await pg.mouse.move(640, 400); await pg.mouse.down(); await pg.mouse.move(640, 470, steps=4); await pg.evaluate('__gg.step(1/30, 3)')
        gv = await pg.evaluate('__gg.guide()'); pw = await pg.is_visible('#power.show')
        check('aiming: power meter + partial aim guide (Medium)', pw and gv['visible'] and gv['n'] > 3 and 0 < gv['frac'] < 1 and not gv['ring'], (pw, gv))
        check('aiming: the ghost putter pulls back', await pg.evaluate('__gg._dbg.putter.visible && __gg._dbg.putter.rotation.x < -.05'))
        await shot(pg, 'shot-aim.png', 1); await pg.mouse.move(640, 480, steps=2); await pg.mouse.up(); await pg.evaluate('__gg.step(1/30, 4)'); l = await lg_since(pg, k)
